package com.orderflow.operations;

import static org.assertj.core.api.Assertions.assertThat;
import static org.awaitility.Awaitility.await;
import com.fasterxml.jackson.databind.ObjectMapper;import com.orderflow.events.*;import com.orderflow.operations.service.DailyReportService;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.apache.kafka.clients.producer.ProducerRecord;import org.apache.kafka.common.header.internals.RecordHeader;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.Container;import org.testcontainers.junit.jupiter.Testcontainers;import org.testcontainers.kafka.KafkaContainer;import org.testcontainers.utility.DockerImageName;
@SpringBootTest @Testcontainers class OperationsFlowIT{@Container static final PostgreSQLContainer<?> POSTGRES=new PostgreSQLContainer<>("postgres:16-alpine");@Container static final KafkaContainer KAFKA=new KafkaContainer(DockerImageName.parse("apache/kafka-native:3.9.1"));@DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",POSTGRES::getJdbcUrl);r.add("spring.datasource.username",POSTGRES::getUsername);r.add("spring.datasource.password",POSTGRES::getPassword);r.add("spring.kafka.bootstrap-servers",KAFKA::getBootstrapServers);r.add("eureka.client.enabled",()->false);r.add("app.operations.reporting.enabled",()->false);r.add("app.scheduler.retention-delay",()->"24h");}@Autowired JdbcTemplate jdbc;@Autowired KafkaTemplate<String,String> kafka;@Autowired ObjectMapper mapper;@Autowired DailyReportService reports;@BeforeEach void reset(){jdbc.update("delete from daily_report");jdbc.update("delete from operational_incident");jdbc.update("delete from daily_operational_metric");jdbc.update("delete from processed_event");jdbc.update("delete from scheduled_job_run");jdbc.update("delete from scheduled_job_lock");}@Test void duplicateKafkaEventsDoNotInflateVolumesAndReportUpsertIsIdempotent()throws Exception{Instant at=Instant.now().minus(Duration.ofDays(1));UUID order=UUID.randomUUID();UUID customer=UUID.randomUUID();EventMetadata metadata=new EventMetadata(UUID.randomUUID(),EventType.PAYMENT_SUCCEEDED,1,"ORDER",order,at,"operations-it",null,"payment-service");var event=new PaymentSucceededEvent(metadata,UUID.randomUUID(),order,customer,"SIMULATOR","provider-1",new BigDecimal("25.50"),"USD",at);send("orderflow.payment-events.v1",event,metadata);send("orderflow.payment-events.v1",event,metadata);await().atMost(Duration.ofSeconds(15)).untilAsserted(()->{assertThat(jdbc.queryForObject("select count(*) from daily_operational_metric where metric_name in ('PAYMENT_SUCCEEDED','PAYMENT_VOLUME')",Long.class)).isEqualTo(2);assertThat(jdbc.queryForObject("select count_value from daily_operational_metric where metric_name='PAYMENT_SUCCEEDED'",Long.class)).isEqualTo(1);assertThat(jdbc.queryForObject("select decimal_value from daily_operational_metric where metric_name='PAYMENT_VOLUME'",BigDecimal.class)).isEqualByComparingTo("25.50");assertThat(jdbc.queryForObject("select count(*) from processed_event",Long.class)).isEqualTo(1);});reports.catchUp();reports.catchUp();assertThat(jdbc.queryForObject("select count(*) from daily_report",Long.class)).isEqualTo(1);assertThat(jdbc.queryForObject("select payment_volume from daily_report",BigDecimal.class)).isEqualByComparingTo("25.50");}private void send(String topic,Object event,EventMetadata metadata)throws Exception{ProducerRecord<String,String> record=new ProducerRecord<>(topic,metadata.aggregateId().toString(),mapper.writeValueAsString(event));record.headers().add(new RecordHeader("eventType",metadata.eventType().name().getBytes(StandardCharsets.UTF_8)));record.headers().add(new RecordHeader("eventVersion",Integer.toString(metadata.eventVersion()).getBytes(StandardCharsets.UTF_8)));kafka.send(record).get();}}
